//' \ -e "s|(\s*action\s*\(\s*type\s*=\s*["]omfwd["].*?)(streamdriver\.permittedpeer\|tls\.permittedpeer\|streamdriverpermittedpeer)\s*=\s*["][^"]*["](.*\))|\1streamdriver.permittedpeer="$rsyslog_remote_loghost_address"\3|gI" \ "$file" if ! grep -qPzi '(?s)\s*action\s*\(\s*type\s*=\s*["]omfwd["].*?(streamdriver\.permittedpeer|tls\.permittedpeer|streamdriverpermittedpeer)\s*=.*?\).*' "$file"; then sed -i -E -e 'H;$!d;x;s/^
